UPDATE physicaldurability 
SET durabilitymetric = COALESCE(gripdur, 0) + COALESCE(drophtm * 10, 0) + COALESCE(bendforce, 0) + COALESCE(twistdeg, 0) + COALESCE(cablebend, 0) + COALESCE(usbconndur, 0);

ALTER TABLE physicaldurability ADD COLUMN durability_metric numeric;

UPDATE physicaldurability 
SET durability_metric = COALESCE(gripdur, 0) + COALESCE(ROUND(drophtm * 10), 0) + COALESCE(bendforce, 0) + COALESCE(twistdeg, 0) + COALESCE(cablebend, 0) + COALESCE(usbconndur, 0)
WHERE gripdur IS NOT NULL OR drophtm IS NOT NULL OR bendforce IS NOT NULL OR twistdeg IS NOT NULL OR cablebend IS NOT NULL OR usbconndur IS NOT NULL;

