ALTER TABLE physicaldurability ADD COLUMN durability_metric numeric;

UPDATE physicaldurability 
SET durability_metric = (SELECT AVG(COALESCE(p2.gripdur, 0) + COALESCE(p2.bendforce, 0)) FROM physicaldurability p2 JOIN interactionandcontrol i2 ON p2.physregistry = i2.interactphysref JOIN deviceidentity d2 ON i2.interactdevref = d2.devregistry WHERE d2.devregistry = (SELECT d3.devregistry FROM interactionandcontrol i3 JOIN deviceidentity d3 ON i3.interactdevref = d3.devregistry WHERE i3.interactphysref = physicaldurability.physregistry LIMIT 1));

