ALTER TABLE physicaldurability ADD COLUMN durability_metric numeric;

UPDATE physicaldurability 
SET durability_metric = COALESCE(gripdur, 0) + COALESCE(bendforce, 0) + COALESCE(twistdeg, 0) + COALESCE(cablebend, 0) + COALESCE(usbconndur, 0) + COALESCE(ROUND(drophtm * 10), 0);

ALTER TABLE physicaldurability ADD COLUMN durability_metric numeric;

UPDATE physicaldurability 
SET durability_metric = COALESCE(gripdur, 0) + COALESCE(bendforce, 0) + COALESCE(twistdeg, 0);

WITH durability_data AS (
    SELECT physregistry, 
           COALESCE(gripdur, 0) + COALESCE(bendforce, 0) + COALESCE(twistdeg, 0) + COALESCE(cablebend, 0) + COALESCE(usbconndur, 0) + COALESCE(ROUND(drophtm * 10), 0) AS durability_metric
    FROM physicaldurability
)
SELECT * FROM durability_data;
